INSERT INTO `baidu_content` VALUES ('24020920005', 0, '央视《新闻联播》主播拜年', '央视《新闻联播》主播拜年', '玉兔辞旧新春到,金龙腾飞气象新!新的一年,祝愿我们每一个人振奋龙马精神,身体健康、阖家幸福、龙年大吉,祝愿我们伟大的祖国风调雨顺、国泰民安、繁荣昌盛。《新闻联播》给大家拜年啦!', '2024-02-09 21:15:15', NULL, '红星新闻', 'http://www.baidu.com/link?url=R4fEawiTqu1gPYTjbSPKWh9V_Tul0pzPTpdMbgGDIqr8zL22pT_fr7qAFOG3pozBV4OoG7TSET9o1T5BwhjboK', 'https://baijiahao.baidu.com/s?id=1790419532257458171');
