INSERT INTO `baidu_content` VALUES ('24021011000', 0, '团圆年|总书记说“年味”', '团圆年|总书记说“年味”', '那达慕是深受蒙古族群众喜爱的民族特色活动。2014年春节前夕,在传统的祈福仪式上,习近平总书记按照蒙古族习俗,用无名指蘸上用银碗盛着的鲜牛奶弹了三下,祝福来年风调雨顺,五畜兴旺,人民幸福安康。', '2024-02-10 11:38:51', NULL, '央视新闻', 'http://www.baidu.com/link?url=C4yGNH_Ue8v8HcM4TnGSO4_FP3bAEpjEgYtEtesFvjRaHaNN1Mr0Kx12j_qL_aqmfRizcg6jH9ARrU07EtR58fjI0HYZELxWteeNH92KVNC', 'https://baijiahao.baidu.com/s?id=1790473079681059711&wfr=spider&for=pc');
