INSERT INTO `baidu_content` VALUES ('24021116002', 1, '聚餐时桌子突然炸了全家人淡定举杯', '聚餐时桌子突然炸了全家人淡定举杯', '2月10日,黑龙江大兴安岭,大年初一吃饭时桌子突然炸了,全家人围坐淡定举杯。拍摄者称,后面在饭店订的菜。', '2024-02-11 16:45:51', NULL, '中工网', 'http://www.baidu.com/link?url=j5KNSzgIE9CqHv_a3GKYCUay4Xjky8tOGEwVt0BTriBk678ZhWQBUMfNlTjL9PwkuE4tbJiBu5E6Ae9gtGw-eeD0SdYEFnCAgvsu_5lCXFG', 'https://baijiahao.baidu.com/s?id=1790583091333202103&wfr=spider&for=pc');
