INSERT INTO `baidu_content` VALUES ('24021221036', 0, '日本火山列岛地区发生6.1级地震 震源深度250千米', '日本火山列岛地区发生6.1级地震 震源深度250千米', '中新网2月12日电 据中国地震台网正式测定:02月12日19时19分在日本火山列岛地区(北纬22.05度,东经142.85度)发生6.1级地震,震源深度250千米。', '2024-02-12 21:11:44', NULL, '环球时报', 'http://www.baidu.com/link?url=QL-TZIpgR8M9sCDQpHMsvPdtivhU9iKskwhrCKos2ciyp1TloUwL-GzPeHBNsS7xNuZ-3rHhUKCxkK3ursa_es7_sMLs0znEB5qBeibu1mq', 'https://baijiahao.baidu.com/s?id=1790697082183346597&wfr=spider&for=pc');
