INSERT INTO `baidu_content` VALUES ('24021810006', 0, '《摔跤吧!爸爸》中饰演“小芭比塔”的演员去世,年仅19岁', '《摔跤吧!爸爸》中饰演“小芭比塔”的演员去世,年仅19岁', '新京报讯(记者滕朝)据外媒报道,曾在印度电影《摔跤吧!爸爸》中饰演“小芭比塔”的苏哈妮·巴特纳格尔于2月7日因身体不适入院,抢救后不幸于2月16日去世,年仅19岁。演员阿米尔·汗通过公司发文悼念,表示《摔跤吧!爸爸》失去了这样一位有天赋的年轻女孩将是不完整的,她永远是大家心中的明星。', '2024-02-18 11:31:59', NULL, '新京报', 'http://www.baidu.com/link?url=JXiRPzxSEx1vg5sqa-q4wsJGgjOT-kekxyyjjMCKVjeaajRVM_kWdtRoHjXlIhl0MUGR2XTT4Qd2LU1ZiWeWAFbiNHysLjF2mPuezmkz4wG', 'https://baijiahao.baidu.com/s?id=1791204435957576352&wfr=spider&for=pc');
INSERT INTO `baidu_content` VALUES ('24021810006', 1, '《摔跤吧!爸爸》小演员去世,年仅19岁', '《摔跤吧!爸爸》小演员去世,年仅19岁', '阿米尔·汗通过公司发文悼念苏哈妮。他表示为这一消息深感悲痛,并向苏哈妮的家人表示衷心的哀悼,“这样一个才华横溢的年轻女孩,这样一个拍摄团队的成员......如果没有苏哈妮,《摔跤吧!爸爸》将是不完整的。”', '2024-02-18 11:31:59', NULL, '红星新闻', 'http://www.baidu.com/link?url=JXiRPzxSEx1vg5sqa-q4wsJGgjOT-kekxyyjjMCKVjeaajRVM_kWdtRoHjXlIhl0LJHTw3krH-8ntwvU9Q_Ib04HAbNcHIz3zvgTVR7-MSC', 'https://baijiahao.baidu.com/s?id=1791204279451327570&wfr=spider&for=pc');
