INSERT INTO `baidu_content` VALUES ('24021908037', 0, '美国明州发生枪击事件已致4死', '美国明州发生枪击事件已致4死', '据美联社报道,当地时间2月18日,美国明尼苏达州伯恩斯维尔市发生一起枪击事件,造成2名警察和1名消防员死亡,该案嫌疑人也已经死亡。', '2024-02-19 08:34:18', NULL, '红星新闻', 'http://www.baidu.com/link?url=aaQiE6ctKrwVjk3MEVhtR7zvuyHddMuwjsIbTPfvZXeP7dUcR768IC26W5vofkS--b3VNmK3kKOuJlazaj2i-a', 'https://baijiahao.baidu.com/s?id=1791281066618099571');
