INSERT INTO `baidu_content` VALUES ('24022014048', 0, '上千名医生集体辞职!韩国医疗系统危机将升至最高级', '上千名医生集体辞职!韩国医疗系统危机将升至最高级', '鉴于这些医生是急诊科和治疗危重病患的主力军,外界担忧韩国医疗一线恐陷入混乱。本月早些时候,医疗界出现集体辞职迹象时,韩国保健福祉部将医疗系统危机级别上调至第二高的“警惕”。\n按韩联社说法,如果这些医生20日集体停工,医疗系统危机级别将进一步提升至最高级“严重”。', '2024-02-20 14:44:56', NULL, '鲁中晨报', 'http://www.baidu.com/link?url=61dH6cGC0xNCS0pW9t6qnSM36MIIHj_NASQclINcPu1QrnhsA_o4a9aTz8bSeah8alHzJOBWHmWQzxG5ZgRX-m1PkReFK-D3zbpL2liu-8C', 'https://baijiahao.baidu.com/s?id=1791398466780989289&wfr=spider&for=pc');
INSERT INTO `baidu_content` VALUES ('24022014048', 1, '韩国大批医生集体辞职 医疗系统危机将升至最高级', '韩国大批医生集体辞职 医疗系统危机将升至最高级', '鉴于这些医生是急诊科和治疗危重病患的主力军,外界担忧韩国医疗一线恐陷入混乱。本月早些时候,医疗界出现集体辞职迹象时,韩国保健福祉部将医疗系统危机级别上调至第二高的“警惕”。按韩联社说法,如果这些医生20日集体停工,医疗系统危机级别将进一步提升至最高级“严重”。', '2024-02-20 14:44:56', NULL, '中国青年网', 'http://www.baidu.com/link?url=61dH6cGC0xNCS0pW9t6qnSM36MIIHj_NASQclINcPu1QrnhsA_o4a9aTz8bSeah8fyREH0jU58YjAn7WAIEHBjYRrBuLKy77T8JvBhAxIFy', 'https://baijiahao.baidu.com/s?id=1791370247497338650&wfr=spider&for=pc');
INSERT INTO `baidu_content` VALUES ('24022014048', 2, '韩国大批医生集体辞职抗议扩招,医疗系统危机或将升...', '韩国大批医生集体辞职抗议扩招，医疗系统危机或将升至最高级', '鉴于这些医生是急诊科和治疗危重病患的主力军,外界担忧韩国医疗一线恐陷入混乱。2月早些时候,医疗界出现集体辞职迹象时,韩国保健福祉部将医疗系统危机级别上调至第二高的“警惕”。报道指出,如果这些医生20日集体停工,医疗系统危机级别将进一步提升至最高级“严重”。', '2024-02-20 14:44:56', NULL, '澎湃新闻', 'http://www.baidu.com/link?url=61dH6cGC0xNCS0pW9t6qnSM36MIIHj_NASQclINcPu1QrnhsA_o4a9aTz8bSeah81WOpbZRL_h9veFe-tCfrdN6B0APrt_M3-BoBZv45Mv7', 'https://baijiahao.baidu.com/s?id=1791383805640160932&wfr=spider&for=pc');
