INSERT INTO `baidu_content` VALUES ('24022023001', 0, '河南河北山西多地下“霰”:形状似米粒大小', '河南河北山西多地下“霰”:形状似米粒大小', '气象专家介绍,霰又称雪丸或软雹,由白色不透明的近似球状(有时呈圆锥形)的、有雪状结构的冰相粒子组成的固态降水,\n直径2~5mm,着硬地常反跳,松脆易碎。', '2024-02-20 23:49:46', NULL, '驱动之家', 'http://www.baidu.com/link?url=0o9WEUUMJkkB69352M6a2_85Snp9O9Va2wkbD0IkS0_6rNxfXLPVH4yUATYT7t9GUHVPiuZKSrR_5KQsoE-IfK', 'https://news.mydrivers.com/1/964/964388.htm');
