INSERT INTO `baidu_realtime` VALUES ('24022207015', '女子指尖藏瘤 手指莫名剧痛10年', '谢女士的右手无名指总是莫名疼痛，饱受10年指痛困扰，最终在武汉市第四医院手外科找到了手指疼痛的“元凶”——指下血管球瘤。 ', '2024-02-22 07:54:50', 'https://www.baidu.com/s?wd=%E5%A5%B3%E5%AD%90%E6%8C%87%E5%B0%96%E8%97%8F%E7%98%A4+%E6%89%8B%E6%8C%87%E8%8E%AB%E5%90%8D%E5%89%A7%E7%97%9B10%E5%B9%B4&sa=fyb_news&rsv_dl=fyb_news', NULL);
